// Pure, deterministic — no Date / Math.random / IO.
// Route each responsibility to exactly one OAuth role.
function roleFor(fact) {
  switch (fact) {
    case "holds the user's password":           return "authorization-server";
    case "authenticates the user, mints tokens": return "authorization-server";
    case "never sees the password, gets a token": return "client";
    case "initiates the redirect to /authorize":  return "client";
    case "validates a token, then serves files":  return "resource-server";
    default:                                       return "UNKNOWN";
  }
}

// Route each token to the single job it is permitted to perform.
function jobFor(token) {
  if (token === "access-token") return "call the API (Authorization: Bearer)";
  if (token === "id-token")     return "prove who the user is (read by client)";
  return "REJECT: unknown token";
}

// Guardrail: the ID token must never be sent to an API.
function sendToApi(token) {
  return token === "access-token" ? "ACCEPT" : "REJECT: id-token is not for APIs";
}

const facts = [
  "holds the user's password",
  "never sees the password, gets a token",
  "validates a token, then serves files",
  "initiates the redirect to /authorize",
  "authenticates the user, mints tokens",
];

const lines = [];
for (const f of facts) lines.push(`role[${f}] = ${roleFor(f)}`);
lines.push(`job[access-token] = ${jobFor("access-token")}`);
lines.push(`job[id-token] = ${jobFor("id-token")}`);
lines.push(`api[access-token] = ${sendToApi("access-token")}`);
lines.push(`api[id-token] = ${sendToApi("id-token")}`);
console.log(lines.join("\n"));
